    const s = [...nums].sort((a, b) => a - b);
    const lowerBound = (x) => {
        let lo = 0, hi = s.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (s[mid] < x) lo = mid + 1; else hi = mid;
        }
        return lo;
    };
    return nums.map(lowerBound);
};

