class Solution:
    def smallerNumbersThanCurrent(self, nums: List[int]) -> List[int]:
        freq = [0] * 102
        for x in nums:
            freq[x + 1] += 1
        for v in range(1, 102):
            freq[v] += freq[v - 1]
        return [freq[x] for x in nums]

