    vector<int> smallerNumbersThanCurrent(vector<int>& nums) {
        vector<int> freq(102, 0);
        for (int x : nums) freq[x + 1]++;
        for (int v = 1; v <= 101; v++) freq[v] += freq[v - 1];
        vector<int> res;
        for (int x : nums) res.push_back(freq[x]);
        return res;
    }
};

